package com.seatcare.worker;
import android.app.*;
import android.bluetooth.*;
import android.bluetooth.le.*;
import android.content.*;
import android.os.*;
import androidx.core.app.NotificationCompat;
import androidx.core.app.NotificationManagerCompat;
import com.getcapacitor.JSObject;
import org.json.JSONArray;
import java.nio.charset.StandardCharsets;
import java.util.*;

/** Sensor owner lives outside the WebView: screen-off BLE, assessment, history, notifications. */
public class SeatSensorService extends Service {
 static SeatSensorService instance;SensorHistory history;
 private static final UUID SERVICE=UUID.fromString("6e400001-b5a3-f393-e0a9-e50e24dcca9e"),RX=UUID.fromString("6e400002-b5a3-f393-e0a9-e50e24dcca9e"),TX=UUID.fromString("6e400003-b5a3-f393-e0a9-e50e24dcca9e"),CCC=UUID.fromString("00002902-0000-1000-8000-00805f9b34fb");
 private final Handler handler=new Handler(Looper.getMainLooper());private final SensorLogic logic=new SensorLogic();
 private BluetoothLeScanner scanner;private BluetoothGatt gatt;private BluetoothGattCharacteristic rx;private String code="",name="",status="disconnected";private double[] values;private boolean connected=false,degraded=false,staleNotified=false,writing=false;private long lastAt=0,lastElapsed=0,lastEmit=0;
 private final Runnable timeout=()->fail("연결 시간이 초과됐어요. 방석 전원과 거리를 확인해 주세요.");
 @Override public void onCreate(){super.onCreate();instance=this;history=new SensorHistory(this);channels(this);}
 @Override public int onStartCommand(Intent intent,int flags,int startId){if(intent!=null&&"STOP".equals(intent.getAction())){stopMonitoring();return START_NOT_STICKY;}startForeground(100,notification(this,"Seat Care 감지 중","방석 연결과 자세 변화를 확인합니다.",true));code=intent==null?"":intent.getStringExtra("code");if(code==null||!code.matches("[0-9A-F]{6}")){fail("앱에서 방석을 다시 연결해 주세요.");return START_NOT_STICKY;}handler.removeCallbacks(tick);handler.post(tick);startScan();return START_NOT_STICKY;}
 @Override public IBinder onBind(Intent intent){return null;}
 private void startScan(){closeGatt();try{BluetoothManager manager=getSystemService(BluetoothManager.class);BluetoothAdapter adapter=manager.getAdapter();if(adapter==null||!adapter.isEnabled()){fail("Bluetooth를 켜 주세요.");return;}scanner=adapter.getBluetoothLeScanner();status="checking";SeatSensorPlugin.emit(snapshot());scanner.startScan(Collections.singletonList(new ScanFilter.Builder().setServiceUuid(new ParcelUuid(SERVICE)).build()),new ScanSettings.Builder().setScanMode(ScanSettings.SCAN_MODE_LOW_LATENCY).build(),scan);handler.postDelayed(timeout,15000);}catch(Exception e){fail("Bluetooth 검색 권한과 기기 상태를 확인해 주세요.");}}
 private final ScanCallback scan=new ScanCallback(){@Override public void onScanResult(int type,ScanResult result){handler.post(()->{String advertised=result.getScanRecord()==null?null:result.getScanRecord().getDeviceName();if(advertised==null||!advertised.equalsIgnoreCase("ESP32-P-"+code)||gatt!=null)return;try{scanner.stopScan(this);name=advertised;gatt=result.getDevice().connectGatt(SeatSensorService.this,false,callback,BluetoothDevice.TRANSPORT_LE);}catch(Exception e){fail("방석에 연결하지 못했어요.");}});}@Override public void onScanFailed(int errorCode){handler.post(()->fail("방석 검색에 실패했어요. 다시 시도해 주세요."));}};
 private final BluetoothGattCallback callback=new BluetoothGattCallback(){
  @Override public void onConnectionStateChange(BluetoothGatt g,int result,int state){handler.post(()->{if(g!=gatt)return;if(result!=BluetoothGatt.GATT_SUCCESS||state==BluetoothProfile.STATE_DISCONNECTED){notifyUser(SeatSensorService.this,"Seat Care · 연결 확인","방석 연결이 끊겨 자세 감지가 중단됐어요. 앱을 열어 다시 연결해 주세요.");fail("방석 연결이 끊겼어요.");return;}if(state==BluetoothProfile.STATE_CONNECTED){if(!g.requestMtu(64))g.discoverServices();}});}
  @Override public void onMtuChanged(BluetoothGatt g,int mtu,int result){handler.post(()->{if(g==gatt)g.discoverServices();});}
  @Override public void onServicesDiscovered(BluetoothGatt g,int result){handler.post(()->{if(g!=gatt)return;BluetoothGattService service=g.getService(SERVICE);rx=service==null?null:service.getCharacteristic(RX);BluetoothGattCharacteristic tx=service==null?null:service.getCharacteristic(TX);if(result!=BluetoothGatt.GATT_SUCCESS||rx==null||tx==null){fail("Seat Care 통신 채널을 찾지 못했어요.");return;}g.setCharacteristicNotification(tx,true);BluetoothGattDescriptor descriptor=tx.getDescriptor(CCC);if(descriptor==null){fail("센서 알림 채널이 없어요.");return;}if(Build.VERSION.SDK_INT>=33)g.writeDescriptor(descriptor,BluetoothGattDescriptor.ENABLE_NOTIFICATION_VALUE);else{descriptor.setValue(BluetoothGattDescriptor.ENABLE_NOTIFICATION_VALUE);g.writeDescriptor(descriptor);}});}
  @Override public void onDescriptorWrite(BluetoothGatt g,BluetoothGattDescriptor descriptor,int result){handler.post(()->{if(g!=gatt)return;if(result!=BluetoothGatt.GATT_SUCCESS){fail("센서 수신을 시작하지 못했어요.");return;}connected=true;status="checking";handler.removeCallbacks(timeout);SeatSensorPlugin.emit(snapshot());try{command("GET_CALIBRATION_STATUS");}catch(Exception e){fail(e.getMessage());}});}
  @Override public void onCharacteristicChanged(BluetoothGatt g,BluetoothGattCharacteristic characteristic,byte[] data){handler.post(()->{if(g==gatt)packet(new String(data,StandardCharsets.UTF_8).trim());});}
  @Override public void onCharacteristicChanged(BluetoothGatt g,BluetoothGattCharacteristic characteristic){if(Build.VERSION.SDK_INT<33){byte[] data=characteristic.getValue();handler.post(()->{if(g==gatt)packet(new String(data,StandardCharsets.UTF_8).trim());});}}
  @Override public void onCharacteristicWrite(BluetoothGatt g,BluetoothGattCharacteristic characteristic,int result){handler.post(()->{writing=false;if(g==gatt&&result!=BluetoothGatt.GATT_SUCCESS)SeatSensorPlugin.emit(new JSObject().put("type","error").put("message","보정 명령을 보내지 못했어요. 다시 시도해 주세요."));});}
 };
 void command(String command){if(!Arrays.asList("GET_CALIBRATION_STATUS","CALIBRATE_ZERO","CALIBRATE_BALANCE","CONTINUE_ZERO_CALIBRATION","CONTINUE_BALANCE_CALIBRATION").contains(command))throw new IllegalArgumentException("지원하지 않는 명령이에요.");if(gatt==null||rx==null||!connected)throw new IllegalStateException("방석을 먼저 연결해 주세요.");if(writing)throw new IllegalStateException("이전 명령 처리 중이에요. 잠시 후 다시 시도해 주세요.");if(command.startsWith("CONTINUE"))degraded=true;if(command.equals("CALIBRATE_ZERO")){degraded=false;status="ZERO_CALIBRATING";}if(command.equals("CALIBRATE_BALANCE"))status="BALANCE_CALIBRATING";logic.reset();byte[] bytes=command.getBytes(StandardCharsets.UTF_8);boolean ok;if(Build.VERSION.SDK_INT>=33)ok=gatt.writeCharacteristic(rx,bytes,BluetoothGattCharacteristic.WRITE_TYPE_DEFAULT)==BluetoothStatusCodes.SUCCESS;else{rx.setWriteType(BluetoothGattCharacteristic.WRITE_TYPE_DEFAULT);rx.setValue(bytes);ok=gatt.writeCharacteristic(rx);}if(!ok)throw new IllegalStateException("보정 명령을 보내지 못했어요.");writing=true;handler.postDelayed(()->writing=false,5000);}
 private void packet(String packet){long at=System.currentTimeMillis(),elapsed=SystemClock.elapsedRealtime();if(packet.matches("S:(SETUP_REQUIRED|ZERO_REQUIRED|ZERO_CALIBRATING|CALIBRATING|BALANCE_REQUIRED|BALANCE_CALIBRATING|READY|ZERO_FAILED|CALIBRATION_FAILED|ZERO_WARNING|BALANCE_WARNING)(?::[1-5](?:,[1-5])*)?")){status=packet.substring(2).split(":")[0];logic.reset();SeatSensorPlugin.emit(new JSObject().put("type","packet").put("packet",packet).put("at",at));return;}double[] parsed=SensorLogic.parse(packet);if(parsed==null)return;values=parsed;lastAt=at;lastElapsed=elapsed;staleNotified=false;boolean ready=status.equals("READY")&&!degraded;if(logic.update(SensorLogic.assess(values),elapsed,ready)){int lean=SensorLogic.assess(values);String body=SensorLogic.LABELS[lean]+"이 이어지고 있어요. "+SensorLogic.guidance(lean);notifyUser(this,"Seat Care · 자세 주의",body);SeatSensorPlugin.emit(new JSObject().put("type","alert").put("message",body));}if(at-lastEmit>=100){lastEmit=at;SeatSensorPlugin.emit(new JSObject().put("type","packet").put("packet",packet).put("at",at));}}
 private final Runnable tick=new Runnable(){public void run(){boolean fresh=connected&&status.equals("READY")&&!degraded&&lastElapsed>0&&SystemClock.elapsedRealtime()-lastElapsed<2000;if(!fresh)logic.reset();history.sample(System.currentTimeMillis(),fresh?values:null,name);if(connected&&status.equals("READY")&&lastElapsed>0&&SystemClock.elapsedRealtime()-lastElapsed>5000&&!staleNotified){staleNotified=true;notifyUser(SeatSensorService.this,"Seat Care · 수신 확인","새 센서값을 받지 못해 자세 감지가 중단됐어요.");}handler.postDelayed(this,1000);}};
 JSObject snapshot(){return new JSObject().put("type","connection").put("connected",connected).put("device",name).put("status",status).put("degraded",degraded).put("at",lastAt).put("values",values==null?null:org.json.JSONObject.wrap(values));}
 private void fail(String message){SeatSensorPlugin.emit(new JSObject().put("type","error").put("message",message));stopMonitoring();}
 void stopMonitoring(){closeGatt();status="disconnected";connected=false;values=null;lastAt=0;logic.reset();history.save();SeatSensorPlugin.emit(snapshot());stopForeground(STOP_FOREGROUND_REMOVE);stopSelf();}
 private void closeGatt(){handler.removeCallbacks(timeout);try{if(scanner!=null)scanner.stopScan(scan);if(gatt!=null){BluetoothGatt old=gatt;gatt=null;old.disconnect();old.close();}}catch(Exception ignored){}rx=null;connected=false;writing=false;}
 @Override public void onDestroy(){handler.removeCallbacksAndMessages(null);closeGatt();history.save();instance=null;super.onDestroy();}
 static void channels(Context context){if(Build.VERSION.SDK_INT>=26){NotificationManager n=context.getSystemService(NotificationManager.class);n.createNotificationChannel(new NotificationChannel("seat-monitor","방석 연결 상태",NotificationManager.IMPORTANCE_LOW));n.createNotificationChannel(new NotificationChannel("seat-alerts","자세 주의 알림",NotificationManager.IMPORTANCE_HIGH));}}
 private static Notification notification(Context context,String title,String body,boolean ongoing){Intent open=new Intent(context,MainActivity.class);PendingIntent content=PendingIntent.getActivity(context,0,open,PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);NotificationCompat.Builder b=new NotificationCompat.Builder(context,ongoing?"seat-monitor":"seat-alerts").setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle(title).setContentText(body).setStyle(new NotificationCompat.BigTextStyle().bigText(body)).setContentIntent(content).setOngoing(ongoing).setAutoCancel(!ongoing).setPriority(ongoing?NotificationCompat.PRIORITY_LOW:NotificationCompat.PRIORITY_HIGH);if(ongoing){PendingIntent stop=PendingIntent.getService(context,1,new Intent(context,SeatSensorService.class).setAction("STOP"),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);b.addAction(0,"감지 중지",stop);}return b.build();}
 static void notifyUser(Context context,String title,String body){channels(context);if(NotificationManagerCompat.from(context).areNotificationsEnabled())try{NotificationManagerCompat.from(context).notify(101,notification(context,title,body,false));}catch(SecurityException ignored){}}
}
